#include <string>

class Solution {
public:
    bool checkAsciiPalindromic(std::string s) {
        int l = 0, r = (int)s.size() - 1;
        while (l < r) {
            if (s[l++] != s[r--]) return false;
        }
        return true;
    }
};

class Solution {
    public boolean checkAsciiPalindromic(String s) {
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (s.charAt(l++) != s.charAt(r--)) return false;
        }
        return true;
    }
}

function checkAsciiPalindromic(s) {
    let l = 0, r = s.length - 1;
    while (l < r) {
        if (s.charCodeAt(l++) !== s.charCodeAt(r--)) return false;
    }
    return true;
}
